import{_ as i,a0 as l,w as r,s as d,ao as a,I as t,x as o,a1 as p,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"什麼是 Linux “oops”？ | LCTT x X-CMD","titleTemplate":false,"description":"什麼是 Linux “oops”？ | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"什麼是 Linux “oops”？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"什麼是 Linux “oops”？ | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180215 What is a Linux -oops","title":"什麼是 Linux “oops”？","tag":"201804","desc":""},"relativePath":"201804/20180215 What is a Linux -oops.md","filePath":"[post].md"}'),u={name:"201804/20180215 What is a Linux -oops.md"};function g(k,s,b,m,f,h){const e=l("Link");return r(),d("div",null,[s[21]||(s[21]=a(`<h1 id="什麼是-linux-oops" tabindex="-1">什麼是 Linux “oops”？ <a class="header-anchor" href="#什麼是-linux-oops" aria-label="Permalink to “什麼是 Linux “oops”？”">​</a></h1><blockquote><p>Linux 內核正在盯着你，當它檢測到系統上運行的某些東西違反了正常內核行為時，它會關閉系統併發出一個“oops”！</p></blockquote><p><img src="https://images.idgesg.net/images/article/2018/02/broken-wine-glass-100749404-large.jpg" alt=""></p><p>如果你檢查你的 Linux 系統上運行的進程，你可能會對一個叫做 “kerneloops” 的進程感到好奇。提示一下，它是 “kernel oops”，而不是 “kerne loops”。</p><p>坦率地説，“oops” 是 Linux 內核的一部分出現了偏差行為。你有做錯了什麼嗎？可能沒有。但有一些不對勁。而那個做了錯事的進程可能已經被 CPU 結束。最糟糕的是，內核可能會報錯並突然關閉系統。</p><p>請注意，“oops” 不是首字母縮略詞。它不代表像“<ruby>面向對象的編程和系統<rt>object-oriented programming and systems</rt></ruby>” 或“<ruby>超出程序規範<rt>out of procedural specs</rt></ruby>” 之類的東西。它實際上就是“哎呀” （oops），就像你剛掉下一杯酒或踩在你的貓身上。哎呀！ “oops” 的複數是 “oopses”。</p><p>oops 意味着系統上運行的某些東西違反了內核有關正確行為的規則。也許代碼嘗試採取不允許的代碼路徑或使用無效指針。不管它是什麼，內核 —— 總是在監測進程的錯誤行為 —— 很可能會阻止特定進程，並將它做了什麼的消息寫入控制台、 <code>/var/log/dmesg</code> 或 <code>/var/log/kern.log</code> 中。</p><p>oops 可能是由內核本身引起的，也可能是某些進程試圖讓內核違反在系統上能做的事以及它們被允許做的事。</p><p>oops 將生成一個<ruby>崩潰簽名<rt>crash signature</rt></ruby>，這可以幫助內核開發人員找出錯誤並提高代碼質量。</p><p>系統上運行的 kerneloops 進程可能如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kernoops 881 1 0 Feb11 ? 00:00:01 /usr/sbin/kerneloops</span></span></code></pre></div><p>你可能會注意到該進程不是由 root 運行的，而是由名為 “kernoops” 的用户運行的，並且它的運行時間極少。實際上，分配給這個特定用户的唯一任務是運行 kerneloops。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo grep kernoops /etc/passwd</span></span>
<span class="line"><span>kernoops:x:113:65534:Kernel Oops Tracking Daemon,,,:/:/bin/false</span></span></code></pre></div>`,13)),t("p",null,[s[1]||(s[1]=o("如果你的 Linux 系統不帶有 kerneloops（比如 Debian），你可以考慮添加它。查看這個 ",-1)),p(e,{href:"https://packages.debian.org/stretch/kerneloops"},{default:n(()=>[...s[0]||(s[0]=[o("Debian 頁面",-1)])]),_:1}),s[2]||(s[2]=o("瞭解更多信息。",-1))]),s[22]||(s[22]=a('<h3 id="什麼時候應該關注-oops" tabindex="-1">什麼時候應該關注 oops？ <a class="header-anchor" href="#什麼時候應該關注-oops" aria-label="Permalink to “什麼時候應該關注 oops？”">​</a></h3><p>一般 oops 沒什麼大不了的。它在一定程度上取決於特定進程所扮演的角色。它也取決於 oops 的類別。</p><p>有些 oops 很嚴重，會導致<ruby>系統恐慌<rt>system panic</rt></ruby>。從技術上講，系統恐慌是 oops 的一個子集（即更嚴重的 oops）。當內核檢測到的問題足夠嚴重以至於內核認為它（內核）必須立即停止運行以防止數據丟失或對系統造成其他損害時會出現。因此，系統需要暫停並重新啓動，以防止任何不一致導致不可用或不可靠。所以系統恐慌實際上是為了保護自己免受不可挽回的損害。</p><p>總之，所有的內核恐慌都是 oops，但並不是所有的 oops 都是內核恐慌。</p><p><code>/var/log/kern.log</code> 和相關的輪轉日誌（<code>/var/log/kern.log.1</code>、<code>/var/log/kern.log.2</code> 等）包含由內核生成並由 syslog 處理的日誌。</p>',5)),t("p",null,[s[4]||(s[4]=o("kerneloops 程序收集並默認將錯誤信息提交到 ",-1)),p(e,{href:"http://oops.kernel.org/"},{default:n(()=>[...s[3]||(s[3]=[o("http://oops.kernel.org/",-1)])]),_:1}),s[5]||(s[5]=o("，在那裏它會被分析並呈現給內核開發者。此進程的配置詳細信息在 ",-1)),s[6]||(s[6]=t("code",null,"/etc/kerneloops.conf",-1)),s[7]||(s[7]=o(" 文件中指定。你可以使用下面的命令輕鬆查看設置：",-1))]),s[23]||(s[23]=a(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cat /etc/kerneloops.conf | grep -v ^# | grep -v ^$</span></span>
<span class="line"><span>[sudo] password for shs:</span></span>
<span class="line"><span>allow-submit = ask</span></span>
<span class="line"><span>allow-pass-on = yes</span></span>
<span class="line"><span>submit-url = http://oops.kernel.org/submitoops.php</span></span>
<span class="line"><span>log-file = /var/log/kern.log</span></span>
<span class="line"><span>submit-pipe = /usr/share/apport/kernel_oops</span></span></code></pre></div><p>在上面的（默認）設置中，內核問題可以被提交，但要求用户獲得許可。如果設置為 <code>allow-submit = always</code>，則不會詢問用户。</p><p>調試內核問題是使用 Linux 系統的更高級技巧之一。幸運的是，大多數 Linux 用户很少或從沒有經歷過 oops 或內核恐慌。不過，知道 kerneloops 這樣的進程在系統中執行什麼操作，瞭解可能會報告什麼以及系統何時遇到嚴重的內核衝突也是很好的。</p><hr>`,4)),t("p",null,[s[9]||(s[9]=o("via: ",-1)),p(e,{href:"https://www.networkworld.com/article/3254778/linux/what-is-a-linux-oops.html"},{default:n(()=>[...s[8]||(s[8]=[o("https://www.networkworld.com/article/3254778/linux/what-is-a-linux-oops.html",-1)])]),_:1})]),t("p",null,[s[13]||(s[13]=o("作者：",-1)),p(e,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:n(()=>[...s[10]||(s[10]=[o("Sandra Henry-Stocker",-1)])]),_:1}),s[14]||(s[14]=o(" 譯者：",-1)),p(e,{href:"https://github.com/geekpi"},{default:n(()=>[...s[11]||(s[11]=[o("geekpi",-1)])]),_:1}),s[15]||(s[15]=o(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[12]||(s[12]=[o("wxy",-1)])]),_:1})]),t("p",null,[s[18]||(s[18]=o("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[16]||(s[16]=[o("LCTT",-1)])]),_:1}),s[19]||(s[19]=o(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:n(()=>[...s[17]||(s[17]=[o("Linux中國",-1)])]),_:1}),s[20]||(s[20]=o(" 榮譽推出",-1))])])}const C=i(u,[["render",g]]);export{w as __pageData,C as default};
